  private static Map<String, String> formFields(String body) {
    Map<String, String> fields = new HashMap<>();
    for (String pair : body.split("&", -1)) {
      int eq = pair.indexOf('=');
      fields.put(
          java.net.URLDecoder.decode(
              pair.substring(0, eq), java.nio.charset.StandardCharsets.UTF_8),
          java.net.URLDecoder.decode(
              pair.substring(eq + 1), java.nio.charset.StandardCharsets.UTF_8));
    }
    return fields;
  }

  @Test
  void bhvAuthOauthTwoTokenMgr022RefreshGrantCarriesTheRefreshTokenAndTheClientCredentialsOnly() {
    // RFC 6749 §6: the refresh grant sends grant_type and the cached
    // refresh_token, plus the client credentials; nothing else from the
    // original grant (here the one-time code) is replayed.
    java.util.List<String> bodies = new java.util.ArrayList<>();
    ApiClient client =
        (method, url, headers, body) -> {
          bodies.add(String.valueOf(body));
          if (bodies.size() == 1) {
            return new ApiHttpResponse(
                200,
                "{\"access_token\":\"old-access\","
                    + "\"refresh_token\":\"old-refresh\",\"expires_in\":0}",
                Map.of());
          }
          return new ApiHttpResponse(
              200, "{\"access_token\":\"new-access\",\"expires_in\":3600}", Map.of());
        };
    OAuth2TokenManager manager = new OAuth2TokenManager();
    manager.setApiClient(client);

    Map<String, String> params = new HashMap<>();
    params.put("grant_type", "authorization_code");
    params.put("code", "one-time-code");
    params.put("client_id", "my-client");
    params.put("client_secret", "my-secret");
    manager.getAccessToken("https://auth.example.com/token", params);
    String token = manager.getAccessToken("https://auth.example.com/token", params);

    assertEquals("new-access", token);
    assertEquals(2, bodies.size());
    assertEquals(
        Map.of(
            "grant_type",
            "refresh_token",
            "refresh_token",
            "old-refresh",
            "client_id",
            "my-client",
            "client_secret",
            "my-secret"),
        formFields(bodies.get(1)));
  }

