  @Test
  void bhvAuthOauthTwoTokenMgr016FailedRefreshFallsBackToTheOriginalGrant() {
    // A rejected refresh token (revoked, expired) must not strand the
    // caller: the manager re-runs the original grant with the original
    // parameters, in the third request.
    java.util.List<String> bodies = new java.util.ArrayList<>();
    ApiClient client =
        (method, url, headers, body) -> {
          bodies.add(String.valueOf(body));
          return switch (bodies.size()) {
            case 1 ->
                new ApiHttpResponse(
                    200,
                    "{\"access_token\":\"old-access\","
                        + "\"refresh_token\":\"old-refresh\",\"expires_in\":0}",
                    Map.of());
            case 2 -> new ApiHttpResponse(400, "{\"error\":\"invalid_grant\"}", Map.of());
            default ->
                new ApiHttpResponse(
                    200, "{\"access_token\":\"fresh-access\",\"expires_in\":3600}", Map.of());
          };
        };
    OAuth2TokenManager manager = new OAuth2TokenManager();
    manager.setApiClient(client);

    Map<String, String> params = new HashMap<>();
    params.put("grant_type", "password");
    params.put("username", "alice");
    params.put("password", "s3cret");
    manager.getAccessToken("https://auth.example.com/token", params);
    String token = manager.getAccessToken("https://auth.example.com/token", params);

    assertEquals("fresh-access", token);
    assertEquals(3, bodies.size());
    assertEquals("refresh_token", formFields(bodies.get(1)).get("grant_type"));
    assertEquals(params, formFields(bodies.get(2)));
  }

