  /*
   * Bucket 3.2 — token POSTs must invoke the noRedirect=true overload.
   * We capture the boolean flag on a fake client to assert the contract.
   */
  @Test
  void bhvAuthOauthTwoTokenMgr034TokenPostInvokesNoRedirectOverload() {
    java.util.concurrent.atomic.AtomicReference<Boolean> seenFlag =
        new java.util.concurrent.atomic.AtomicReference<>(null);
    ApiClient client =
        new ApiClient() {
          @Override
          public ApiHttpResponse sendRequest(
              String method, String url, Map<String, String> headers, @Nullable Object body) {
            // Must NOT be called: the manager must use the 5-arg overload.
            seenFlag.set(false);
            return new ApiHttpResponse(
                200, "{\"access_token\":\"t\",\"expires_in\":3600}", Map.of());
          }

          @Override
          public ApiHttpResponse sendRequest(
              String method,
              String url,
              Map<String, String> headers,
              @Nullable Object body,
              boolean noRedirect) {
            seenFlag.set(noRedirect);
            return new ApiHttpResponse(
                200, "{\"access_token\":\"t\",\"expires_in\":3600}", Map.of());
          }
        };
    OAuth2TokenManager manager = new OAuth2TokenManager();
    manager.setApiClient(client);

    Map<String, String> params = new HashMap<>();
    params.put("grant_type", "client_credentials");
    manager.getAccessToken("https://auth.example.com/token", params);

    assertEquals(true, seenFlag.get(), "token POST must pass noRedirect=true to the ApiClient");
  }

  /*
   * Bucket 3.2 — if the token endpoint replies with ANY 3xx (because
   * followRedirects was bypassed), the manager must treat it as an
   * error rather than caching nothing and silently returning. RFC 6749
   * §3.2 forbids redirects at the token endpoint; we reject the whole
   * 300-399 range (302 and 307 both shown below, plus 301/303).
   */
  @org.junit.jupiter.params.ParameterizedTest
  @org.junit.jupiter.params.provider.ValueSource(ints = {301, 302, 303, 307, 308})
  void bhvAuthOauthTwoTokenMgr033TokenEndpointRedirectIsRejected(int status) {
    ApiClient client =
        new ApiClient() {
          @Override
          public ApiHttpResponse sendRequest(
              String method, String url, Map<String, String> headers, @Nullable Object body) {
            return sendRequest(method, url, headers, body, false);
          }

          @Override
          public ApiHttpResponse sendRequest(
              String method,
              String url,
              Map<String, String> headers,
              @Nullable Object body,
              boolean noRedirect) {
            return new ApiHttpResponse(
                status, "", Map.of("location", "https://attacker.example/take"));
          }
        };
    OAuth2TokenManager manager = new OAuth2TokenManager();
    manager.setApiClient(client);

    Map<String, String> params = new HashMap<>();
    params.put("grant_type", "client_credentials");
    params.put("client_secret", "super-secret");

    // A 3xx is a non-2xx answer from the token endpoint, so it is an
    // OAuth2ServerException carrying the redirect status.
    OAuth2ServerException ex =
        assertThrowsExactly(
            OAuth2ServerException.class,
            () -> manager.getAccessToken("https://auth.example.com/token", params));
    assertEquals(status, ex.getStatusCode());
  }

  @Test
  void bhvAuthOauthTwoTokenMgr019InvalidateAccessTokenTriggersSingleRefetchUnderConcurrency()
      throws InterruptedException {
    // After invalidation, 10 concurrent callers must coalesce into exactly
    // ONE additional network round-trip (single-flight), all observing the
    // same freshly fetched token.
    AtomicInteger callCount = new AtomicInteger(0);
    ApiClient client =
        (method, url, headers, body) -> {
          int n = callCount.incrementAndGet();
          try {
            Thread.sleep(50);
          } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
          }
          return new ApiHttpResponse(
              200, "{\"access_token\":\"tok" + n + "\",\"expires_in\":3600}", Map.of());
        };
    OAuth2TokenManager manager = new OAuth2TokenManager();
    manager.setApiClient(client);

    Map<String, String> params = new HashMap<>();
    params.put("grant_type", "client_credentials");

    String first = manager.getAccessToken("https://auth.example.com/token", params);
    assertEquals("tok1", first);
    assertEquals(1, callCount.get());

    manager.invalidateAccessToken();

    int threadCount = 10;
    String[] tokens = new String[threadCount];
    Thread[] threads = new Thread[threadCount];
    for (int i = 0; i < threadCount; i++) {
      final int idx = i;
      threads[i] =
          new Thread(
              () -> tokens[idx] = manager.getAccessToken("https://auth.example.com/token", params));
    }
    for (Thread t : threads) {
      t.start();
    }
    for (Thread t : threads) {
      t.join();
    }

    // Exactly one additional network call (callCount went 1 -> 2).
    assertEquals(2, callCount.get(), "invalidate + concurrent callers must produce one refetch");
    for (String token : tokens) {
      assertEquals("tok2", token, "all callers must observe the same refreshed token");
    }
  }

  @Test
  void bhvAuth002InvalidatingBeforeAnyExchangeRaisesNothingAndSendsNoRequest() {
    AtomicInteger calls = new AtomicInteger(0);
    OAuth2TokenManager manager = new OAuth2TokenManager();
    manager.setApiClient(
        (method, url, headers, body) -> {
          calls.incrementAndGet();
          return new ApiHttpResponse(200, "{}", Map.of());
        });

    manager.invalidateAccessToken();

    assertEquals(0, calls.get());
    assertNull(manager.getRefreshToken());
  }

  @Test
  void bhvAuth013CancellingTheCallStopsTheTokenRequestWithoutWaitingForTheEndpoint()
      throws Exception {
    // A token endpoint that accepts the connection and never answers. The interrupted
    // call reports the cancellation at once instead of waiting for the endpoint.
    try (java.net.ServerSocket silent = new java.net.ServerSocket(0)) {
      OAuth2TokenManager manager = new OAuth2TokenManager();
      manager.setApiClient(new DefaultApiClient());
      Map<String, String> params = new HashMap<>();
      params.put("grant_type", "client_credentials");
      String tokenUrl = "http://127.0.0.1:" + silent.getLocalPort() + "/token";

      Thread.currentThread().interrupt();
      try {
        assertThrowsExactly(
            CancellationException.class, () -> manager.getAccessToken(tokenUrl, params));
        assertFalse(manager.isExchanged());
      } finally {
        Thread.interrupted();
      }
    }
  }

  @Test
  void bhvAuth017TokenBodyWritesASpaceAsPlusAndEncodesOtherReservedPunctuation() {
    AtomicReference<String> sent = new AtomicReference<>();
    OAuth2TokenManager manager = new OAuth2TokenManager();
    manager.setApiClient(
        (method, url, headers, body) -> {
          sent.set(String.valueOf(body));
          return new ApiHttpResponse(
              200, "{\"access_token\":\"at\",\"expires_in\":3600}", Map.of());
        });

    manager.getAccessToken(TOKEN_URL, Map.of("q", "a b~-._*!/"));

    assertEquals("q=a+b~-._%2A%21%2F", sent.get());
  }

  @Test
  void bhvAuth026FailedRefreshAndFailedFallbackRaiseTheFallbackErrorWithItsStatus() {
    // The first grant issues a refresh token and an access token that is already
    // stale. The refresh is rejected, and so is the fallback grant: the caller must see
    // the fallback grant's error with its own status code.
    var responses =
        new Object() {
          int call = 0;
        };
    ApiClient client =
        (method, url, headers, body) -> {
          responses.call++;
          if (responses.call == 1) {
            return new ApiHttpResponse(
                200,
                "{\"access_token\":\"at\",\"refresh_token\":\"rt\",\"expires_in\":0}",
                Map.of());
          }
          if (responses.call == 2) {
            return new ApiHttpResponse(401, "{\"error\":\"invalid_grant\"}", Map.of());
          }
          return new ApiHttpResponse(
              400,
              "{\"error\":\"invalid_client\",\"error_description\":\"fallback rejected\"}",
              Map.of());
        };
    OAuth2TokenManager manager = new OAuth2TokenManager();
    manager.setApiClient(client);
    Map<String, String> params = new HashMap<>();
    params.put("grant_type", "client_credentials");
    manager.getAccessToken(TOKEN_URL, params);

    OAuth2ServerException ex =
        assertThrowsExactly(
            OAuth2ServerException.class, () -> manager.getAccessToken(TOKEN_URL, params));

    assertEquals(400, ex.getStatusCode());
    assertEquals("invalid_client", ex.getCode());
    assertEquals(3, responses.call);
  }

  @Test
  void bhvLangjava061FailedFirstExchangeLeavesNoSessionAndIsNotExchanged() {
    OAuth2TokenManager manager = new OAuth2TokenManager();
    manager.setApiClient(fakeClient(400, "{\"error\":\"invalid_grant\"}"));
    Map<String, String> params = new HashMap<>();
    params.put("grant_type", "authorization_code");

    assertThrowsExactly(
        OAuth2ServerException.class, () -> manager.exchange(TOKEN_URL, params, Map.of()));

    assertFalse(manager.isExchanged());
    assertNull(manager.getRefreshToken());
  }

  @Test
  void bhvErrors082MalformedOptionalFieldsAreDroppedAndAValidCodeIsKept() {
    OAuth2TokenManager manager = new OAuth2TokenManager();
    manager.setApiClient(
        fakeClient(
            400, "{\"error\":\"invalid_grant\",\"error_description\":42,\"error_uri\":{\"x\":1}}"));
    Map<String, String> params = new HashMap<>();
    params.put("grant_type", "client_credentials");

    OAuth2ServerException ex =
        assertThrowsExactly(
            OAuth2ServerException.class, () -> manager.getAccessToken(TOKEN_URL, params));

    assertEquals("invalid_grant", ex.getCode());
    assertNull(ex.getDescription());
    assertNull(ex.getUri());

    OAuth2TokenManager numeric = new OAuth2TokenManager();
    numeric.setApiClient(fakeClient(400, "{\"error\":7,\"error_description\":\"bad\"}"));

    OAuth2ServerException nonString =
        assertThrowsExactly(
            OAuth2ServerException.class, () -> numeric.getAccessToken(TOKEN_URL, params));

    assertNull(nonString.getCode());
  }

  @Test
  void bhvMisc001ReplacingTheTokenWhileOthersReadIsRaceFree() throws InterruptedException {
    // Every read gets one complete token that was set; the last one set is the one used.
    String[] tokens = {"token-a", "token-b"};
    Set<String> allowed = Set.of(tokens);
    OAuth2TokenManager manager = new OAuth2TokenManager();
    manager.setAccessToken(tokens[0]);
    Map<String, String> params = Map.of("grant_type", "client_credentials");
    ConcurrentLinkedQueue<String> unexpected = new ConcurrentLinkedQueue<>();

    Thread writer =
        new Thread(
            () -> {
              for (int i = 0; i < 2000; i++) {
                manager.setAccessToken(tokens[i % 2]);
              }
            });
    Thread reader =
        new Thread(
            () -> {
              for (int i = 0; i < 2000; i++) {
                String seen = manager.getAccessToken(TOKEN_URL, params);
                if (!allowed.contains(seen)) {
                  unexpected.add(seen);
                }
              }
            });
    writer.start();
    reader.start();
    writer.join();
    reader.join();

    assertTrue(unexpected.isEmpty(), unexpected.toString());
    manager.setAccessToken("final-token");
    assertEquals("final-token", manager.getAccessToken(TOKEN_URL, params));
  }

  @Test
  void bhvAuth057RejectedRefreshFallsBackToTheOriginalGrant() {
    java.util.List<String> bodies = new java.util.ArrayList<>();
    ApiClient client =
        (method, url, headers, body) -> {
          bodies.add(body != null ? body.toString() : "");
          int n = bodies.size();
          if (n == 1) {
            return new ApiHttpResponse(
                200,
                "{\"access_token\":\"first\",\"expires_in\":0,\"refresh_token\":\"r1\"}",
                Map.of());
          }
          if (n == 2) {
            return new ApiHttpResponse(400, "{\"error\":\"invalid_grant\"}", Map.of());
          }
          return new ApiHttpResponse(
              200, "{\"access_token\":\"fallback\",\"expires_in\":3600}", Map.of());
        };
    OAuth2TokenManager manager = new OAuth2TokenManager();
    manager.setApiClient(client);
    Map<String, String> grant = new HashMap<>();
    grant.put("grant_type", "client_credentials");
    manager.getAccessToken("https://auth.example.com/token", grant, Map.of(), null);

    String token = manager.getAccessToken("https://auth.example.com/token", grant, Map.of(), null);

    assertEquals("fallback", token);
    assertTrue(bodies.get(2).contains("grant_type=client_credentials"), bodies.get(2));
  }

